package handlers
import (
 "net/http"
 "net/mail"
 "regexp"
 "strings"
 "fluxo/models"
 "fluxo/utils"
 "github.com/gorilla/mux"
 "github.com/google/uuid"
 "golang.org/x/crypto/bcrypt"
)
var hexColor=regexp.MustCompile(`^#[0-9a-fA-F]{6}$`)
func(a *API)Sectors(w http.ResponseWriter,r *http.Request){id:=mux.Vars(r)["id"];if r.Method=="GET"{if id!=""{var s models.Setor;err:=a.Repo.DB.QueryRow(r.Context(),"SELECT id::text,nome,capacidade,cor FROM setores WHERE id=$1",id).Scan(&s.ID,&s.Nome,&s.Capacidade,&s.Cor);if err!=nil{utils.DBError(w,err);return};utils.JSON(w,200,s);return};rows,err:=a.Repo.DB.Query(r.Context(),"SELECT id::text,nome,capacidade,cor FROM setores ORDER BY nome");if err!=nil{utils.DBError(w,err);return};defer rows.Close();result:=[]models.Setor{};for rows.Next(){var s models.Setor;if err=rows.Scan(&s.ID,&s.Nome,&s.Capacidade,&s.Cor);err!=nil{utils.DBError(w,err);return};result=append(result,s)};if err=rows.Err();err!=nil{utils.DBError(w,err);return};utils.JSON(w,200,result);return};if !manager(w,r){return};if r.Method=="DELETE"{tag,err:=a.Repo.DB.Exec(r.Context(),"DELETE FROM setores WHERE id=$1",id);if err!=nil{utils.DBError(w,err);return};if tag.RowsAffected()==0{utils.Error(w,404,"Setor não encontrado.");return};utils.JSON(w,204,nil);return};var s models.Setor;if !utils.Decode(w,r,&s){return};s.Nome=strings.TrimSpace(s.Nome);if s.Nome==""||len([]rune(s.Nome))>120||s.Capacidade<1||s.Capacidade>10000||!hexColor.MatchString(s.Cor){utils.Error(w,400,"Verifique nome, capacidade e cor do setor.");return};var err error;status:=200;if r.Method=="POST"{status=201;err=a.Repo.DB.QueryRow(r.Context(),"INSERT INTO setores(nome,capacidade,cor) VALUES($1,$2,$3) RETURNING id::text",s.Nome,s.Capacidade,s.Cor).Scan(&s.ID)}else{s.ID=id;err=a.Repo.DB.QueryRow(r.Context(),"UPDATE setores SET nome=$2,capacidade=$3,cor=$4 WHERE id=$1 RETURNING id::text",id,s.Nome,s.Capacidade,s.Cor).Scan(&s.ID)};if err!=nil{utils.DBError(w,err);return};utils.JSON(w,status,s)}
func(a *API)Users(w http.ResponseWriter,r *http.Request){id:=mux.Vars(r)["id"];if r.Method=="GET"{if id!=""{var u models.Usuario;err:=a.Repo.DB.QueryRow(r.Context(),"SELECT id::text,nome,email,perfil,setor_id::text FROM usuarios WHERE id=$1",id).Scan(&u.ID,&u.Nome,&u.Email,&u.Perfil,&u.SetorID);if err!=nil{utils.DBError(w,err);return};utils.JSON(w,200,u);return};rows,err:=a.Repo.DB.Query(r.Context(),"SELECT id::text,nome,email,perfil,setor_id::text FROM usuarios ORDER BY nome");if err!=nil{utils.DBError(w,err);return};defer rows.Close();result:=[]models.Usuario{};for rows.Next(){var u models.Usuario;if err=rows.Scan(&u.ID,&u.Nome,&u.Email,&u.Perfil,&u.SetorID);err!=nil{utils.DBError(w,err);return};result=append(result,u)};if err=rows.Err();err!=nil{utils.DBError(w,err);return};utils.JSON(w,200,result);return};if !manager(w,r){return};if r.Method=="DELETE"{if id==User(r).ID{utils.Error(w,400,"Você não pode excluir sua própria conta.");return};tag,err:=a.Repo.DB.Exec(r.Context(),"DELETE FROM usuarios WHERE id=$1",id);if err!=nil{utils.DBError(w,err);return};if tag.RowsAffected()==0{utils.Error(w,404,"Usuário não encontrado.");return};utils.JSON(w,204,nil);return};var u models.Usuario;if !utils.Decode(w,r,&u){return};u.Nome=strings.TrimSpace(u.Nome);u.Email=strings.ToLower(strings.TrimSpace(u.Email));parsed,err:=mail.ParseAddress(u.Email);_,sectorErr:=uuid.Parse(u.SetorID);if u.Nome==""||len([]rune(u.Nome))>120||err!=nil||parsed.Address!=u.Email||len(u.Email)>254||sectorErr!=nil||!contains([]string{"gestor","servidor"},u.Perfil){utils.Error(w,400,"Dados da pessoa inválidos.");return};if id==User(r).ID&&u.Perfil!="gestor"{utils.Error(w,400,"Você não pode retirar seu próprio acesso de gestor.");return};var hash []byte;if u.Senha!=""{if len(u.Senha)<8||len([]byte(u.Senha))>72{utils.Error(w,400,"A senha deve conter de 8 a 72 bytes.");return};hash,err=bcrypt.GenerateFromPassword([]byte(u.Senha),bcrypt.DefaultCost);if err!=nil{utils.Error(w,500,"Não foi possível salvar a senha.");return}};if r.Method=="POST"&&len(hash)==0{utils.Error(w,400,"Informe uma senha de pelo menos 8 caracteres.");return};status:=200;if r.Method=="POST"{status=201;err=a.Repo.DB.QueryRow(r.Context(),"INSERT INTO usuarios(nome,email,perfil,setor_id,senha_hash) VALUES($1,$2,$3,$4,$5) RETURNING id::text",u.Nome,u.Email,u.Perfil,u.SetorID,string(hash)).Scan(&u.ID)}else{u.ID=id;tx,txErr:=a.Repo.DB.Begin(r.Context());if txErr!=nil{utils.DBError(w,txErr);return};defer tx.Rollback(r.Context());var previous string;if err=tx.QueryRow(r.Context(),"SELECT setor_id::text FROM usuarios WHERE id=$1 FOR UPDATE",id).Scan(&previous);err!=nil{utils.DBError(w,err);return};if previous!=u.SetorID{var active bool;if err=tx.QueryRow(r.Context(),"SELECT EXISTS(SELECT 1 FROM tarefas WHERE servidor_id=$1 OR revisor_id=$1)",id).Scan(&active);err!=nil{utils.DBError(w,err);return};if active{utils.Error(w,409,"Reatribua as tarefas desta pessoa antes de mudar seu setor.");return}};err=tx.QueryRow(r.Context(),"UPDATE usuarios SET nome=$2,email=$3,perfil=$4,setor_id=$5,senha_hash=CASE WHEN $6='' THEN senha_hash ELSE $6 END WHERE id=$1 RETURNING id::text",id,u.Nome,u.Email,u.Perfil,u.SetorID,string(hash)).Scan(&u.ID);if err==nil{err=tx.Commit(r.Context())}};if err!=nil{utils.DBError(w,err);return};u.Senha="";utils.JSON(w,status,u)}
func(a *API)Config(w http.ResponseWriter,r *http.Request){if r.Method=="PUT"{if !manager(w,r){return};var body struct{Pontos int `json:"pontos_por_tarefa"`};if !utils.Decode(w,r,&body){return};if body.Pontos<1||body.Pontos>1000{utils.Error(w,400,"Use uma pontuação entre 1 e 1000.");return};if _,err:=a.Repo.DB.Exec(r.Context(),"UPDATE configuracoes SET pontos_por_tarefa=$1 WHERE id=1",body.Pontos);err!=nil{utils.DBError(w,err);return}};var points int;if err:=a.Repo.DB.QueryRow(r.Context(),"SELECT pontos_por_tarefa FROM configuracoes WHERE id=1").Scan(&points);err!=nil{utils.DBError(w,err);return};utils.JSON(w,200,map[string]int{"pontos_por_tarefa":points})}
